(function(){
  const canvas=ReefRender.canvas;let api=null,pointerSelected=-1;
  function bind(game,onAction){api={game,onAction};canvas.addEventListener('pointerdown',pointer);canvas.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('keydown',key);}
  function pointer(e){if(!api||api.game.mode!=='playing')return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;let best=-1,dist=.075;api.game.vanes.forEach((v,i)=>{const d=Math.hypot(v.x-x,v.y-y);if(d<dist){dist=d;best=i;}});if(best>=0){const g=api.game,wasSelected=pointerSelected===best;g.selected=best;pointerSelected=best;ReefAudio.wake();if(e.button===2||wasSelected){ReefModel.turn(g,best,e.button===2?-1:1);ReefAudio.turn();api.onAction('turn');}else api.onAction('select');}}
  function key(e){if(!api)return;const g=api.game,k=e.key.toLowerCase();if(['arrowleft','arrowright',' ','enter','arrowup','arrowdown'].includes(k))e.preventDefault();if(k==='p'){api.onAction('pause');return;}if(k==='r'){api.onAction('restart');return;}if(g.mode==='title'||g.mode==='won'||g.mode==='lost'){if(k===' '||k==='enter')api.onAction('start');return;}if(g.mode!=='playing')return;if(k==='arrowleft'||k==='a'){ReefModel.turn(g,g.selected,-1);ReefAudio.turn();api.onAction('turn');}else if(k==='arrowright'||k==='d'){ReefModel.turn(g,g.selected,1);ReefAudio.turn();api.onAction('turn');}else if(k==='arrowup'||k==='w'){g.selected=(g.selected+g.vanes.length-1)%g.vanes.length;api.onAction('select');}else if(k==='arrowdown'||k==='s'){g.selected=(g.selected+1)%g.vanes.length;api.onAction('select');}else if(k===' '||k==='enter'){if(ReefModel.pulse(g)){ReefAudio.pulse();api.onAction('pulse');}}}
  window.ReefControls={bind};
})();
